dcc/probe_catchup_anchor.c.contents:
/* Read-only production-behavior probe. The valid runtime anchor is seeded as
 * the logger would record it; all log files and replacements are private. */
#define _XOPEN_SOURCE 700
#include "idle.c"
#include <assert.h>

static void put_file(const char *path, const char *text)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_EXCL, 0600);
    assert(fd >= 0);
    size_t size = strlen(text);
    assert(write(fd, text, size) == (ssize_t)size && close(fd) == 0);
}

int main(void)
{
    char directory[] = "/tmp/onekey-anchor-probe-XXXXXX";
    assert(mkdtemp(directory));
    char config[CONFIG_PATH_MAX], log[CONFIG_PATH_MAX], archive[CONFIG_PATH_MAX];
    assert(snprintf(config, sizeof config, "%s/config.ini", directory) > 0);
    assert(snprintf(log, sizeof log, "%s/config.ini.log", directory) > 0);
    assert(snprintf(archive, sizeof archive, "%s/archived.log", directory) > 0);
    put_file(log, "[#test] <me> ORIGINAL-SENT-ANCHOR\n[#test] original absence\n");
    struct stat original, replacement;
    assert(stat(log, &original) == 0);

    Idle *idle = calloc(1, sizeof *idle);
    Client *client = calloc(1, sizeof *client);
    App *app = calloc(1, sizeof *app);
    assert(idle && client && app);
    idle->client = client;
    idle->catchup_fd = -1;
    idle->compose_token = 1;
    idle->compose_kind = B_CHANNEL;
    strcpy(idle->compose_target, "#test");
    client->slots[0].used = 1;
    client->slots[0].token = 1;
    client->slots[0].app = app;
    app->cfg.persistent_logging = 1;
    strcpy(app->config_path, config);
    app->buffer_count = 1;
    app->buffers[0].kind = B_CHANNEL;
    strcpy(app->buffers[0].name, "#test");
    app->buffers[0].last_own_log_valid = 1;
    app->buffers[0].last_own_log_offset = 0;

    assert(rename(log, archive) == 0);
    put_file(log, "[#test] <alice> REPLACEMENT-WITHOUT-SENT-ANCHOR\n");
    assert(stat(log, &replacement) == 0);
    assert(original.st_dev != replacement.st_dev || original.st_ino != replacement.st_ino);
    int opened = begin_catchup(idle);
    printf("different_inode=1; retained_memory_anchor=0; begin_catchup=%d; mode_is_catchup=%d\n",
           opened, idle->mode == CATCHUP);
    assert(opened == 1 && idle->mode == CATCHUP);
    char bytes[256];
    ssize_t n = pread(idle->catchup_fd, bytes, sizeof bytes - 1u, 0);
    assert(n > 0); bytes[n] = 0;
    assert(strstr(bytes, "REPLACEMENT-WITHOUT-SENT-ANCHOR") && !strstr(bytes, "ORIGINAL-SENT-ANCHOR"));
    puts("CONFIRMED: same-channel replacement log was accepted as the previous sent-message anchor.");
    puts("Trigger: local private log replacement between sent anchor and /catchup; no hostile network trigger demonstrated.");
    catchup_close(idle);
    free(app); free(client); free(idle);
    assert(unlink(log) == 0 && unlink(archive) == 0 && rmdir(directory) == 0);
    return 0;
}

