network/probe_history.c.contents:
#define main legacy_idle_commands_test_main
#include "test_idle_commands.c"
#undef main
#include "commands.h"

int main(void)
{
    static const char *const cases[] = {
        "/msg CustomAuthBot IDENTIFY SECRET_CANARY",
        "/msg CustomAuthBot ::IDENTIFY SECRET_CANARY",
        "/msg CustomAuthBot : : IDENTIFY SECRET_CANARY",
        "/privmsg CustomAuthBot : LOGIN account SECRET_CANARY",
    };
    Fixture f; init(&f, 1);
    assert(run(&f, "/connect") == IDLE_COMMAND_DONE);
    pump(app(&f));
    assert(app(&f)->registered);
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; ++i) {
        CommandHistory history;
        commands_history_init(&history);
        int result = run(&f, cases[i]);
        assert(result == IDLE_COMMAND_SEND);
        printf("case=%zu accepted_message_plan=1 idle_recordable=%d full_history_added=%d\n",
               i, idle_command_recordable(cases[i]), commands_history_add(&history, cases[i]));
#ifdef HAVE_PLAN_HISTORY_GUARD
        printf("case=%zu actual_plan_history_safe=%d\n", i, app_plan_history_safe(&f.plan));
#endif
        commands_history_free(&history);
    }
    {
        char line[APP_TEXT + 1];
        size_t budget = app_budget(app(&f), "CustomAuthBot", 0);
        const char *prefix = "/msg CustomAuthBot ";
        size_t before = strlen(prefix);
        assert(budget > 5 && before + budget + 64 < sizeof line);
        memcpy(line, prefix, before);
        memset(line + before, 'x', budget);
        memcpy(line + before, "HELP ", 5);
        strcpy(line + before + budget, "IDENTIFY SPLIT_SECRET_CANARY");
        assert(run(&f, line) == IDLE_COMMAND_SEND && f.plan.count == 2);
        assert(!strcmp(f.plan.text + f.plan.chunks[1].offset, "IDENTIFY SPLIT_SECRET_CANARY"));
        CommandHistory history;
        commands_history_init(&history);
        printf("split_case actual_second_chunk_is_identify=1 idle_recordable=%d full_history_added=%d\n",
               idle_command_recordable(line), commands_history_add(&history, line));
#ifdef HAVE_PLAN_HISTORY_GUARD
        printf("split_case actual_plan_history_safe=%d combined_idle_recordable=%d combined_full_history=%d\n",
               app_plan_history_safe(&f.plan),
               app_plan_history_safe(&f.plan) && idle_command_recordable(line),
               app_plan_history_safe(&f.plan) && commands_history_add(&history, line));
#endif
        commands_history_free(&history);
    }
    cleanup(&f);
    return 0;
}

network/probe_presence.c.contents:
#define main legacy_app_test_main
#include "test_app.c"
#undef main

static size_t notices;
static void count_notice(void *context, const App *app, const char *text)
{
    (void)context; (void)app; (void)text;
    ++notices;
}

int main(void)
{
    for (int background = 0; background < 2; ++background) {
        App *a = fresh(0);
        register_plain(a);
        feed(a, ":server 005 tester LINELEN=64 :supported\r\n");
        assert(a->wire_limit == 64);
        output_clear(a);
        memset(a->cfg.background_away_message, 'A', 100);
        a->cfg.background_away_message[100] = 0;
        memset(a->cfg.autoaway_message, 'A', 100);
        a->cfg.autoaway_message[100] = 0;
        a->status_event = count_notice;
        notices = 0;
        if (background) {
            a->cfg.background_away = 1;
            app_set_backgrounded(a, 1);
        } else {
            a->cfg.autoaway_minutes = 1;
            a->last_local_activity = clock_ms - 60000;
        }
        size_t zero_timeouts = 0;
        for (size_t i = 0; i < 1000; ++i) {
            if (!app_timeout(a)) ++zero_timeouts;
            app_network(a, 0);
        }
        printf("mode=%s zero_timeouts=%zu status_callbacks=%zu queued=%zu output_bytes=%zu automatic_away=%d\n",
               background ? "background" : "local-idle", zero_timeouts, notices,
               a->control_count + a->chat_count, a->net->output_len, a->automatic_away);
        assert(a->registered && !a->control_count && !a->net->output_len);
        destroy(a);
    }
    return 0;
}

